export const DEMO_GENERATED_HTML: string = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Soloist – The Solo Developer Issue Tracker</title>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;600&family=Merriweather:wght@700&display=swap\" rel=\"stylesheet\">\n  <style>\n    :root {\n      --ink-black: #1C1C1C;\n      --paper-white: #FFFFFF;\n      --graphite: #333333;\n      --signal-amber: #C8801F;\n      --quiet-sage: #6E7F6A;\n      --font-heading: 'Merriweather', serif;\n      --font-body: 'Inter', sans-serif;\n      --max-width: 800px;\n    }\n    *, *::before, *::after { box-sizing: border-box; }\n    body {\n      margin: 0;\n      font-family: var(--font-body);\n      color: var(--graphite);\n      background: var(--paper-white);\n      line-height: 1.6;\n    }\n    a {\n      color: var(--signal-amber);\n      text-decoration: none;\n    }\n    a:focus { outline: 2px solid var(--quiet-sage); outline-offset: 2px; }\n    header {\n      background: var(--ink-black);\n      color: var(--paper-white);\n    }\n    .nav {\n      display: flex;\n      justify-content: center;\n      gap: 2rem;\n      padding: 1rem;\n    }\n    .nav a {\n      color: var(--paper-white);\n      font-weight: 600;\n    }\n    main { padding: 2rem 1rem; }\n    .section {\n      max-width: var(--max-width);\n      margin: 0 auto;\n      padding: 4rem 0;\n    }\n    h1, h2 {\n      font-family: var(--font-heading);\n      margin: 0 0 1rem;\n    }\n    h1 { font-size: 2.5rem; color: var(--ink-black); }\n    h2 { font-size: 2rem; color: var(--ink-black); }\n    p { margin: 0 0 1.5rem; }\n    .hero {\n      text-align: center;\n    }\n    .hero button {\n      background: var(--signal-amber);\n      color: var(--paper-white);\n      border: none;\n      padding: 0.75rem 1.5rem;\n      font-size: 1rem;\n      cursor: pointer;\n      border-radius: 4px;\n    }\n    .hero button:focus { outline: 2px solid var(--quiet-sage); }\n    .task-list {\n      background: var(--paper-white);\n      border: 1px solid #e0e0e0;\n      border-radius: 8px;\n      padding: 1rem;\n    }\n    .task-item {\n      display: flex;\n      justify-content: space-between;\n      padding: 0.5rem 0;\n      border-bottom: 1px solid #f0f0f0;\n    }\n    .task-item:last-child { border-bottom: none; }\n    footer {\n      background: var(--ink-black);\n      color: var(--paper-white);\n      text-align: center;\n      padding: 2rem 1rem;\n      font-size: 0.875rem;\n    }\n    @media (max-width: 600px) {\n      h1 { font-size: 2rem; }\n      h2 { font-size: 1.5rem; }\n      .nav { flex-direction: column; gap: 1rem; }\n    }\n  </style>\n</head>\n<body>\n  <header>\n    <nav class=\"nav\" aria-label=\"Primary\">\n      <a href=\"#dashboard\">Dashboard</a>\n      <a href=\"#backlog\">Backlog</a>\n      <a href=\"#pricing\">Pricing</a>\n      <a href=\"#settings\">Settings</a>\n    </nav>\n  </header>\n\n  <main>\n    <section id=\"hero\" class=\"section hero\">\n      <h1>What are you shipping tonight?</h1>\n      <p>Your active queue is clear. Add a new task or pick one from your backlog to get started.</p>\n      <button type=\"button\" onclick=\"addSampleTask()\">Add Sample Task</button>\n    </section>\n\n    <section id=\"active-tasks\" class=\"section\">\n      <h2>Active Tasks</h2>\n      <p>These are the items you have committed to finishing in this session.</p>\n      <div class=\"task-list\" id=\"taskList\">\n        <!-- tasks will be injected here -->\n      </div>\n    </section>\n\n    <section id=\"dashboard\" class=\"section\">\n      <h2>Dashboard</h2>\n      <p>Quick overview of your current work, progress, and recent activity.</p>\n    </section>\n\n    <section id=\"backlog\" class=\"section\">\n      <h2>Backlog</h2>\n      <p>All ideas, features, and bugs waiting for their turn. Use the Someday bucket to hide low‑priority items.</p>\n    </section>\n\n    <section id=\"pricing\" class=\"section\">\n      <h2>Pricing</h2>\n      <p>Soloist is free for solo developers. No hidden fees, no enterprise lock‑in.</p>\n    </section>\n\n    <section id=\"settings\" class=\"section\">\n      <h2>Settings</h2>\n      <p>Customize keyboard shortcuts, toggle Focus mode, and choose your preferred storage option.</p>\n    </section>\n  </main>\n\n  <footer>\n    <p>&copy; 2026 Soloist. Crafted for the solo developer.</p>\n  </footer>\n\n  <script>\n    const sampleTasks = [\n      {title: 'Write README for new feature', detail: 'Use markdown to format the spec.'},\n      {title: 'Refactor authentication module', detail: 'Apply local‑first storage pattern.'},\n      {title: 'Test focus mode UI', detail: 'Ensure only the active task is visible.'}\n    ];\n    function renderTasks() {\n      const list = document.getElementById('taskList');\n      list.innerHTML = '';\n      sampleTasks.forEach((t, i) => {\n        const div = document.createElement('div');\n        div.className = 'task-item';\n        div.innerHTML = `<span>${t.title}</span><button onclick=\"removeTask(${i})\" aria-label=\"Remove ${t.title}\">✕</button>`;\n        list.appendChild(div);\n      });\n    }\n    function addSampleTask() {\n      renderTasks();\n    }\n    function removeTask(index) {\n      sampleTasks.splice(index, 1);\n      renderTasks();\n    }\n    // Initial render (empty)\n    renderTasks();\n  </script>\n</body>\n</html>";
